code.js:
function factorial(n) {
  if (n <= 1) return 1;        // base case
  return n * factorial(n - 1); // 더 작은 문제로 위임
}

factorial(5); // 5 * 4 * 3 * 2 * 1

function fib(n) {
  if (n <= 1) return n;
  return fib(n - 1) + fib(n - 2);
}

